DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` int NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` int NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `calendar_events`;
CREATE TABLE `calendar_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` date NOT NULL,
  `time` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `venue` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `panel_members` text COLLATE utf8mb4_unicode_ci,
  `result_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `calendar_events_user_id_foreign` (`user_id`),
  CONSTRAINT `calendar_events_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `date`, `time`, `type`, `venue`, `panel_members`, `result_notes`, `created_at`, `updated_at`) VALUES ('1', '1', 'Test Event', '2026-07-29', '08:00 AM', 'Personal', NULL, NULL, NULL, '2026-07-27 11:07:23', '2026-07-27 11:07:23');

DROP TABLE IF EXISTS `cms_contents`;
CREATE TABLE `cms_contents` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `cms_contents` (`key`, `value`, `created_at`, `updated_at`) VALUES ('mock_hr_news', '[{\"id\":1,\"title\":\"NAAP Launches New Employee Wellness Program\",\"date\":\"June 05, 2026\",\"category\":\"Employee Welfare\",\"summary\":\"A comprehensive wellness initiative designed to support the physical and mental health of all NAAP employees. Features include gym memberships, mental health workshops, and flexible work arrangements.\",\"author\":\"HR Department\",\"content\":\"The National Aviation Academy of the Philippines (NAAP) is proud to announce the launch of its comprehensive Employee Wellness Program...\",\"fullContent\":\"The National Aviation Academy of the Philippines (NAAP) is proud to announce the launch of its comprehensive Employee Wellness Program, designed to prioritize the physical, mental, and emotional well-being of its workforce.\\n\\nRecognizing that a healthy team is a productive team, this initiative introduces a suite of benefits aimed at fostering a balanced work-life environment.\\n\\nKey Features of the Program:\\n\\n- Gym Memberships: Subsidized access to partner fitness centers.\\n- Mental Health Support: Free access to counseling services and mental health workshops.\\n- Flexible Work Arrangements: Options for remote work and flexible hours for eligible roles.\\n- Annual Health Screenings: Comprehensive executive check-ups covered by the academy.\\n\\n\\\"Our employees are our greatest asset,\\\" said the HR Director. \\\"This program is a testament to our commitment to creating a supportive and nurturing environment where everyone can thrive.\\\"\\n\\nThe program takes effect immediately, and employees are encouraged to visit the HR portal for enrollment details.\",\"image\":\"data:image\\/jpeg;base64,\\/9j\\/4AAQSkZJRgABAQAAAQABAAD\\/2wCEAAkGBwgHBgkIBwgKCgkLDRYPDQwMDRsUFRAWIB0iIiAdHx8kKDQsJCYxJx8fLT0tMTU3Ojo6Iys\\/RD84QzQ5OjcBCgoKDQwNGg8PGjclHyU3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3Nzc3N\\/\\/AABEIAXUCGAM